INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(34411, 'Luke 23:51', 'Luke', 23, 51, 'خو د هغوی د دې پرېکړې او دې کار سره جوړ نه ؤ او د خدای د پاچاهۍ په انتظار ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_51.mp3', '', 1761754199, 1761754199),
(34412, 'Luke 23:52', 'Luke', 23, 52, 'هغه پیلاتوس ته ورغی او د عیسی مړی یې ترې وغوښت.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_52.mp3', '', 1761754199, 1761754199),
(34413, 'Luke 23:53', 'Luke', 23, 53, 'بیا هغه د صلیب څخه مړی راښکته کړ او د کتان په کفن کې یې تاو کړ او په ګټ کې کیندل شوي قبر کې یې کېښود چې د دې نه مخکې په کې څوک نه ؤ ښخ شوی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_53.mp3', '', 1761754199, 1761754199),
(34414, 'Luke 23:54', 'Luke', 23, 54, 'دا د جمعې ورځ وه، یعنې سبت ته د تیاري نیولو ورځ وه او د سبت ورځ پیل کېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_54.mp3', '', 1761754199, 1761754199),
(34415, 'Luke 23:55', 'Luke', 23, 55, 'کومې ښځې چې د جلیل څخه د عیسی سره راغلې وې یوسف پسې روانې وې. هغوی قبر ولیده چې د عیسی مړی په کې څنګه ایښودل شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_55.mp3', '', 1761754199, 1761754199),
(34416, 'Luke 23:56', 'Luke', 23, 56, 'بیا هغوی بېرته د اورشلیم ښار ته لاړې او د مړي دپاره یې خوشبویه مسالې او عطر تیار کړل او د شریعت د حکم له مخې یې د سبت په ورځ ارام وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke23_verse_56.mp3', '', 1761754199, 1761754199),
(34417, 'Luke 14:1', 'Luke', 14, 1, 'د سبت په یوه ورځ عیسی د ډوډۍ خوړلو دپاره د فریسیانو د ډلې د یو مشر کور ته لاړ او هلته خلکو په ځیر هغه ته کتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_1.mp3', '', 1761754199, 1761754199),
(34418, 'Luke 14:2', 'Luke', 14, 2, 'هلته عیسی ته مخامخ یو سړی ولاړ ؤ چې د پړسوب په ناروغۍ اخته ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_2.mp3', '', 1761754199, 1761754199),
(34419, 'Luke 14:3', 'Luke', 14, 3, 'عیسی د شریعت د عالمانو او فریسیانو څخه پوښتنه وکړه: «ایا د سبت په ورځ د ناروغانو روغول روا دي که نه؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_3.mp3', '', 1761754199, 1761754199),
(34420, 'Luke 14:4', 'Luke', 14, 4, 'خو هغوی غلي پاتې شول. نو عیسی هغه سړی له لاسه ونیوه، هغه یې روغ کړ او رخصت یې کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_4.mp3', '', 1761754199, 1761754199),
(34421, 'Luke 14:5', 'Luke', 14, 5, 'بیا عیسی د هغوی څخه پوښتنه وکړه: «که چېرې د سبت په ورځ په تاسو کې د کوم چا زوی یا غویی په څاه کې ولویږي، نو ایا هغه به یې سمدلاسه راونه باسي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_5.mp3', '', 1761754199, 1761754199),
(34422, 'Luke 14:6', 'Luke', 14, 6, 'خو د هغوی سره د دې خبرې ځواب نه ؤ. عاجزي او مېلمه‌پالنه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_6.mp3', '', 1761754199, 1761754199),
(34423, 'Luke 14:7', 'Luke', 14, 7, 'کله چې عیسی ولیدل چې ځینو مېلمنو کوښښ کاوه د ځانونو دپاره تر ټولو لوړ ځایونه ونیسي، نو هغوی ته یې دا مثال راوړ:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_7.mp3', '', 1761754199, 1761754199),
(34424, 'Luke 14:8', 'Luke', 14, 8, '«کله چې څوک تاسو ته د واده د مېلمستیا دپاره بلنه درکړي نو د مجلس په سر کې مه کښېنئ، ځکه کېدای شي چې ستاسو څخه کوم بل ډېر مهم سړی رابلل شوی وي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_8.mp3', '', 1761754199, 1761754199),
(34425, 'Luke 14:9', 'Luke', 14, 9, 'او ستاسو کوربه چې تاسو دواړه یې رابللي یئ راشي او درته ووایي: ‹خپل ځای دې سړي ته پرېږده.› نو بیا به وشرمېږې او مجبوره به شې چې تر ټولو وروستني ځای کې کښېنې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_9.mp3', '', 1761754199, 1761754199),
(34426, 'Luke 14:10', 'Luke', 14, 10, 'خو کله چې د چا مېلمه شې، نو لاړ شه او تر ټولو وروستني ځای کې کښېنه، ترڅو کله چې کوربه راشي او درته ووایي: ‹ای زما ملګریه! پاس کښېنئ.› په دې به د نورو ټولو مېلمنو په مخکې ستا عزت وشي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_10.mp3', '', 1761754199, 1761754199),
(34427, 'Luke 14:11', 'Luke', 14, 11, 'ځکه څوک چې خپل ځان لوی ګڼي، هغه به خوار شي او څوک چې خپل ځان عاجز کړي، هغه به سرلوړی شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_11.mp3', '', 1761754199, 1761754199),
(34428, 'Luke 14:12', 'Luke', 14, 12, 'بیا عیسی خپل کوربه ته وویل: «کله چې د غرمې یا د ماښام ډوډۍ دپاره څوک راغواړې، نو خپلو ملګرو یا خپلو ورونو یا خپلوانو یا خپلو شتمنو ګاونډیانو ته بلنه مه ورکوه، ځکه چې هغوی به هم بېرته تاته بلنه درکړي او په دې ډول به ستا بدل پوره کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_12.mp3', '', 1761754199, 1761754199),
(34429, 'Luke 14:13', 'Luke', 14, 13, 'خو کله چې مېلمستیا ورکوې، نو غریبانو، شلانو، ګوډانو او ړندو ته بلنه ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_13.mp3', '', 1761754199, 1761754199),
(34430, 'Luke 14:14', 'Luke', 14, 14, 'نو ته به بختور یې، ځکه چې هغوی ستا بدل نه شي پوره کولای. خو د قیامت په ورځ به خدای تاته د نېکانو سره اجر درکړي.» د لویې مېلمستیا مثال (متي ۲۲‏:‌۱‌‏-‌۱۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_14.mp3', '', 1761754199, 1761754199),
(34431, 'Luke 14:15', 'Luke', 14, 15, 'کله چې د حاضرو خلکو څخه یو تن چې په دسترخوان ورسره ناست ؤ دا واورېدل، نو عیسی ته یې وویل: «بختور دي هغه خلک چې د خدای په پاچاهۍ کې به په مېلمستیا کې کښېني.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_15.mp3', '', 1761754199, 1761754199),
(34432, 'Luke 14:16', 'Luke', 14, 16, 'عیسی هغه ته وویل: «یو سړي یوه لویه مېلمستیا جوړه کړه او ډېر خلک یې راوبلل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_16.mp3', '', 1761754199, 1761754199),
(34433, 'Luke 14:17', 'Luke', 14, 17, 'کله چې د ډوډۍ وخت شو، نو خپل نوکر یې مېلمنو پسې ولېږه چې ورته ووایي: ‹راشئ، هرڅه تیار دي.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_17.mp3', '', 1761754199, 1761754199),
(34434, 'Luke 14:18', 'Luke', 14, 18, 'خو هغوی ټولو بهانې پیل کړې. لومړني وویل: ‹ما لږه ځمکه اخیستې ده، باید لاړ شم او هغه ووینم. مهرباني وکړه زما عذر ومنه.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_18.mp3', '', 1761754199, 1761754199),
(34435, 'Luke 14:19', 'Luke', 14, 19, 'بل وویل: ‹ما پنځه جوړې غویان اخیستي دي او روان یم چې هغه امتحان کړم، مهرباني وکړه زما عذر ومنه.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_19.mp3', '', 1761754199, 1761754199),
(34436, 'Luke 14:20', 'Luke', 14, 20, 'او بل یې وویل: ‹ما نوی واده کړی دی، نو له دې امله نه شم درتللی.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_20.mp3', '', 1761754199, 1761754199),
(34437, 'Luke 14:21', 'Luke', 14, 21, 'نوکر بېرته راغی او خپل بادار ته یې دا هرڅه وویل. بادار ډېر په قهر شو او خپل نوکر ته یې وویل: ‹زر زر د ښار لارو او کوڅو ته ووځه او غریبان، شلان، ړانده او ګوډان راوله.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_21.mp3', '', 1761754199, 1761754199),
(34438, 'Luke 14:22', 'Luke', 14, 22, 'کله چې نوکر بېرته راستون شو، نو ویې ویل: ‹باداره! ستاسو امر په ځای شو، خو بیاهم د نورو خلکو دپاره ځای شته.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_22.mp3', '', 1761754199, 1761754199),
(34439, 'Luke 14:23', 'Luke', 14, 23, 'بیا بادار خپل نوکر ته وویل: ‹د ښار څخه دباندې سرکونو او کوڅو ته ووځه او خلک په زوره راوله، ترڅو زما کور ډک شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_23.mp3', '', 1761754199, 1761754199),
(34440, 'Luke 14:24', 'Luke', 14, 24, 'زه تاسو ته وایم چې د هغو خلکو څخه چې لومړی مې ورته بلنه ورکړې وه هېڅوک به هم زما د دې مېلمستیا خوند ونه څکي.›» د مسیح د شاګردۍ بیه (متي ۱۰‏:‌۳۷‌‏-‌۳۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_24.mp3', '', 1761754199, 1761754199),
(34441, 'Luke 14:25', 'Luke', 14, 25, 'یوځل چې د خلکو یوه لویه ډله د عیسی سره روانه وه، عیسی هغوی ته مخ راواړاوه او ورته ویې ویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_25.mp3', '', 1761754199, 1761754199),
(34442, 'Luke 14:26', 'Luke', 14, 26, '«که څوک ماته راځي او هغه د خپل مور، پلار، خپلې ښځې او اولادونو، خویندو او ورونو او حتی د خپل ځان څخه هم زما سره زیاته مینه ونه کړي، هغه نه شي کولای چې زما شاګرد شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_26.mp3', '', 1761754199, 1761754199),
(34443, 'Luke 14:27', 'Luke', 14, 27, 'که چېرې څوک خپل صلیب راوانخلي او ما پسې رانه شي، نو هغه زما شاګرد کېدای نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_27.mp3', '', 1761754199, 1761754199),
(34444, 'Luke 14:28', 'Luke', 14, 28, 'فرض کړئ چې په تاسو کې کوم څوک غواړي یو برج جوړ کړي، ایا هغه به لومړی نه کښېني چې لګښت یې وسنجوي، ترڅو وویني چې د هغه سره دومره پیسې شته چې هغه ورباندې سرته ورسوي یا نه؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_28.mp3', '', 1761754199, 1761754199),
(34445, 'Luke 14:29', 'Luke', 14, 29, 'که نه، نو بنیاد به یې کېږدي، خو وبه نه شي کولای چې سرته یې ورسوي، نو هرڅوک چې هغه وګوري ورپورې وبه خاندي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_29.mp3', '', 1761754199, 1761754199),
(34446, 'Luke 14:30', 'Luke', 14, 30, 'هغوی به وایي چې دې سړي د ودانۍ کار پیل کړ، خو ویې نه شو کولای چې سرته یې ورسوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_30.mp3', '', 1761754199, 1761754199),
(34447, 'Luke 14:31', 'Luke', 14, 31, 'یا کوم داسې پاچا به وي چې د بل پاچا سره د جګړې دپاره ځي او پرته له دې چې لومړی کښېني او فکر وکړي چې ایا د خپل لسو زرو عسکرو سره به وکولای شي د هغه بل پاچا سره چې شل زره لښکر لري، وجنګیږي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_31.mp3', '', 1761754199, 1761754199),
(34448, 'Luke 14:32', 'Luke', 14, 32, 'که چېرې هغه ونه شي کولای، نو مخکې له دې چې دښمن ورته راورسیږي، هغه به استازي ولېږي او د سولې د شرطونو په هکله به ورڅخه غوښتنه وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_32.mp3', '', 1761754199, 1761754199),
(34449, 'Luke 14:33', 'Luke', 14, 33, 'په همدې ډول په تاسو کې هېڅوک تر هغې زما شاګرد کېدای نه شي، ترڅو هر څه چې لري د هغو ټولو څخه تېر نه شي. د بې‌خونده مالګې مثال (متي ۵‏:‌۱۳ او مرقوس ۹‏:‌۵۰)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_33.mp3', '', 1761754199, 1761754199),
(34450, 'Luke 14:34', 'Luke', 14, 34, 'مالګه ښه شی دی، خو که په خپله مالګه بې‌خونده شي، نو هغه به څنګه بېرته خپل خوند پیدا کړي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_34.mp3', '', 1761754199, 1761754199),
(34451, 'Luke 14:35', 'Luke', 14, 35, 'د هغې څخه نور نه د ځمکې دپاره او نه د سرې دپاره کار اخیستل کیږي او خلک هغه لېرې غورځوي. که څوک غوږونه لري، نو هغه دې واوري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke14_verse_35.mp3', '', 1761754199, 1761754199),
(34452, 'John 17:1', 'John', 17, 1, 'د دې خبرو نه وروسته عیسی پورته اسمان ته وکتل او ویې ویل: «پلاره، هغه ساعت رارسېدلی دی. خپل زوی ته جلال ورکړه ترڅو چې زوی دې هم تاته جلال درکړي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_1.mp3', '', 1761754199, 1761754199),
(34453, 'John 17:2', 'John', 17, 2, 'ځکه چې تا هغه ته په ټولو انسانانو باندې واک او اختیار ورکړی دی ترڅو هغو ټولو خلکو ته چې هغه ته دې ورسپارلي دي، تلپاتې ژوندون ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_2.mp3', '', 1761754199, 1761754199),
(34454, 'John 17:3', 'John', 17, 3, 'او تلپاتې ژوندون دا دی چې هغوی تا وپېژني چې ته یوازېنی رښتینی خدای یې او عیسی مسیح چې تا رالېږلی دی، وپېژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_3.mp3', '', 1761754199, 1761754199),
(34455, 'John 17:4', 'John', 17, 4, 'ما د هغه کار په سرته رسولو سره چې تا راته راسپارلی ؤ په دې نړۍ کې تاته جلال درکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_4.mp3', '', 1761754199, 1761754199),
(34456, 'John 17:5', 'John', 17, 5, 'ای پلاره! اوس ماته دې په خپل حضور کې جلال راکړه، هماغه جلال چې د نړۍ د پیدایښت نه مخکې مې ستا په حضور کې درلود.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_5.mp3', '', 1761754199, 1761754199),
(34457, 'John 17:6', 'John', 17, 6, 'ما ستا نوم هغو خلکو ته چې په نړۍ کې دې غوره کړل او ماته دې راکړل، وروپېژانده. هغوی ستا وو او تا ماته راکړل او هغوی ستا په کلام باندې عمل کړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_6.mp3', '', 1761754199, 1761754199),
(34458, 'John 17:7', 'John', 17, 7, 'اوس هغوی پوهیږي چې هرڅه چې تا راکړي دي هغه ستا له خوا دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_7.mp3', '', 1761754199, 1761754199),
(34459, 'John 17:8', 'John', 17, 8, 'ځکه چې هغه پیغام چې تا ماته راکړی دی هغه مې هغوی ته رسولی دی او هغوی قبول کړی دی. هغوی پوهیږي چې دا رښتیا دي چې زه ستا له خوا راغلی یم او په دې باندې ایمان لري چې زه تا رالېږلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_8.mp3', '', 1761754199, 1761754199),
(34460, 'John 17:9', 'John', 17, 9, 'زه د هغوی دپاره دعا کوم، د نړۍ دپاره یې نه کوم. زه د هغو خلکو دپاره دعا کوم چې تا راته راکړي دي ځکه چې هغوی ستا دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_9.mp3', '', 1761754199, 1761754199),
(34461, 'John 17:10', 'John', 17, 10, 'زه چې کوم خلک لرم هغه ستا دي او تا سره چې کوم خلک دي هغه زما دي او د هغو په وسیله زما جلال څرګند شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_10.mp3', '', 1761754199, 1761754199),
(34462, 'John 17:11', 'John', 17, 11, 'زه نور په دې نړۍ کې نه پاتې کېږم او هغوی به لا په دې نړۍ کې پاتې وي او زه تاته درروان یم. ای سپېڅلی پلاره، د خپل نوم په قدرت سره هغه خلک چې ماته دې راکړي وساته، ترڅو هغوی سره یو وي لکه څنګه چې مونږ سره یو یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_11.mp3', '', 1761754199, 1761754199),
(34463, 'John 17:12', 'John', 17, 12, 'هغه وخت چې زه د هغوی سره وم هغوی مې په هغه نوم چې تا راته راکړی ؤ وساتل او د هغوی نه یو هم هلاک نه شو، پرته له یو نه چې باید هلاک شي، ترڅو د خدای د کلام وینا رښتیا شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_12.mp3', '', 1761754199, 1761754199),
(34464, 'John 17:13', 'John', 17, 13, 'خو زه اوس تاته درروان یم او ترڅو پورې چې زه په دې نړۍ کې یم دا خبرې کوم د دې دپاره چې هغوی په خپلو زړونو کې په پوره توګه داسې خوشحالي ولري لکه زما خوشحالي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_13.mp3', '', 1761754199, 1761754199),
(34465, 'John 17:14', 'John', 17, 14, 'ما ستا کلام هغوی ته ورساوه خو د نړۍ خلکو د هغه نه کرکه وکړه، ځکه چې هغوی د دې نړۍ نه دي لکه څنګه چې زه د دې نړۍ نه یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_14.mp3', '', 1761754199, 1761754199),
(34466, 'John 17:15', 'John', 17, 15, 'زه تاته دا دعا نه کوم چې هغوی د دې نړۍ نه لېرې کړې بلکې دا سوال کوم چې هغوی د شیطان نه وساتې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_15.mp3', '', 1761754199, 1761754199),
(34467, 'John 17:16', 'John', 17, 16, 'لکه څنګه چې زه د دې نړۍ نه یم نو هغوی هم د دې نړۍ نه دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_16.mp3', '', 1761754199, 1761754199),
(34468, 'John 17:17', 'John', 17, 17, 'هغوی د خپل کلام په وسیله چې رښتینی کلام دی، وقف کړه چې ستا خدمت وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_17.mp3', '', 1761754199, 1761754199),
(34469, 'John 17:18', 'John', 17, 18, 'لکه څنګه چې تا زه نړۍ ته راولېږلم نو ما هم هغوی نړۍ ته لېږلي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_18.mp3', '', 1761754199, 1761754199),
(34470, 'John 17:19', 'John', 17, 19, 'ما خپل ځان وقف کړ چې ستا خدمت وکړم، د دې دپاره چې هغوی هم په رښتیا سره ستا خدمت ته وقف شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_19.mp3', '', 1761754199, 1761754199),
(34471, 'John 17:20', 'John', 17, 20, 'زه یوازې د دې شاګردانو دپاره دعا نه کوم بلکې د هغو خلکو دپاره یې هم کوم چې د دوی د پیغام په وسیله په ما باندې ایمان راوړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_20.mp3', '', 1761754199, 1761754199),
(34472, 'John 17:21', 'John', 17, 21, 'زه دعا کوم چې هغوی دې سره یو وي. ای پلاره، لکه څنګه چې ته په ما کې یې نو پرېږده چې هغوی دې هم په مونږ کې وي، ترڅو د نړۍ خلک په دې باندې ایمان ولري چې زه تا رالېږلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_21.mp3', '', 1761754199, 1761754199),
(34473, 'John 17:22', 'John', 17, 22, 'کوم جلال چې تا ماته راکړی ؤ هغه ما هغوی ته ورکړ، ترڅو هغوی سره یو وي لکه څنګه چې زه او ته سره یو یو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_22.mp3', '', 1761754199, 1761754199),
(34474, 'John 17:23', 'John', 17, 23, 'زه په هغوی کې اوسېږم او ته په ما کې اوسېږې، ترڅو هغوی په پوره توګه سره یو وي او د نړۍ خلک په دې پوه شي چې زه تا رالېږلی یم او د هغوی سره دومره مینه کوې لکه څنګه چې زما سره یې کوې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_23.mp3', '', 1761754199, 1761754199),
(34475, 'John 17:24', 'John', 17, 24, 'ای پلاره، کوم خلک چې تا ماته راکړي دي زه غواړم چېرته چې زه یم هغوی دې هم زما سره وي، ترڅو زما جلال وویني چې تا ماته راکړی، ځکه تا د نړۍ د پیدایښت نه مخکې ما سره مینه کړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_24.mp3', '', 1761754199, 1761754199),
(34476, 'John 17:25', 'John', 17, 25, 'ای عادل پلاره! نړۍ ته ونه پېژندلې، خو ما پېژندلی یې او دوی پوهیږي چې تا زه رالېږلی یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_25.mp3', '', 1761754199, 1761754199),
(34477, 'John 17:26', 'John', 17, 26, 'ما ته هغوی ته وروپېژندلې چې ته څوک یې او نور به دې هم وروپېژنم، ترڅو هغه مینه چې ته یې په ما کې لرې په هغوی کې یې هم ولرې او زه به په هغوی کې اوسم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john17_verse_26.mp3', '', 1761754199, 1761754199),
(34478, 'John 20:1', 'John', 20, 1, 'د یکشنبې په ورځ سهار وختي چې لا تیاره وه مریم مجدلیه قبر ته راغله او ویې لیدل چې د قبر د خولې نه تیږه لېرې شوې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_1.mp3', '', 1761754199, 1761754199),
(34479, 'John 20:2', 'John', 20, 2, 'نو هغه په منډه منډه شمعون پطروس او هغه شاګرد ته چې په عیسی باندې ډېر ګران ؤ ورغله او هغوی ته یې وویل: «هغوی زمونږ د عیسی مړی د قبر نه وړی او مونږ نه پوهېږو چې په کوم ځای کې یې اچولی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_2.mp3', '', 1761754199, 1761754199),
(34480, 'John 20:3', 'John', 20, 3, 'نو پطروس او هغه بل شاګرد ووتل او د قبر خواته لاړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_3.mp3', '', 1761754199, 1761754199),
(34481, 'John 20:4', 'John', 20, 4, 'هغوی دواړو منډې وهلې، خو هغه بل شاګرد د پطروس نه مخکې شو او د هغه نه لومړی قبر ته ورسېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_4.mp3', '', 1761754199, 1761754199),
(34482, 'John 20:5', 'John', 20, 5, 'هغه قبر ته ورټیټ شو او دننه یې وکتل او کفن یې ولیده چې هلته پروت ؤ، خو قبر ته وردننه نه شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_5.mp3', '', 1761754199, 1761754199),
(34483, 'John 20:6', 'John', 20, 6, 'بیا شمعون پطروس راورسېد او قبر ته ورننوت. هغه هم کفن ولیده چې هلته پروت ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_6.mp3', '', 1761754199, 1761754199),
(34484, 'John 20:7', 'John', 20, 7, 'او هغه دستمال چې د عیسی د سر نه تاو ؤ، هغه د کفن سره نه ؤ، بلکې هغه په خپله قات شوی ؤ او په بل ځای کې پروت ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_7.mp3', '', 1761754199, 1761754199),
(34485, 'John 20:8', 'John', 20, 8, 'بیا هغه بل شاګرد چې مخکې قبر ته رسېدلی ؤ، هم قبر ته ورننوت او چې کله یې هغه ولیده، نو باور یې وکړ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_8.mp3', '', 1761754199, 1761754199),
(34486, 'John 20:9', 'John', 20, 9, 'ځکه چې هغوی لا تر دې وخته پورې د خدای په کلام باندې پوه شوي نه وو چې ویلي یې وو چې عیسی باید د مړو نه بیا راژوندی شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_9.mp3', '', 1761754199, 1761754199),
(34487, 'John 20:10', 'John', 20, 10, 'نو بیا هغه دواړه شاګردان بېرته کور ته لاړل. عیسی مریم مجدلیې ته ښکاره کیږي (متي ۲۸‏:‌۹، ۱۰ او مرقوس ۱۶‏:‌۹‌‏-‌۱۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_10.mp3', '', 1761754199, 1761754199),
(34488, 'John 20:11', 'John', 20, 11, 'خو مریم د قبر نه دباندې ولاړه وه او ژړل یې. هغې لا ژړل چې ټیټه شوه او دننه قبر ته یې وکتل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_11.mp3', '', 1761754199, 1761754199),
(34489, 'John 20:12', 'John', 20, 12, 'او دوه فرښتې یې په سپینو کالیو کې ولیدلې چې په هغه ځای کې چې د عیسی مړی پروت ؤ یوه یې سرته او بله یې پښو ته ناسته وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_12.mp3', '', 1761754199, 1761754199),
(34490, 'John 20:13', 'John', 20, 13, 'هغوی د هغې نه پوښتنه وکړه: «ای ښځې، ته ولې ژاړې؟» هغې ورته وویل: «ځکه چې هغوی زما د استاذ مړی وړی دی او زه نه پوهېږم چې چېرته یې اچولی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_13.mp3', '', 1761754199, 1761754199),
(34491, 'John 20:14', 'John', 20, 14, 'کله چې هغې دا خبره وکړه نو مخ یې راواړاوه او عیسی یې ولیده چې هلته ولاړ دی، خو هغې ونه پېژانده چې دا عیسی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_14.mp3', '', 1761754199, 1761754199),
(34492, 'John 20:15', 'John', 20, 15, 'عیسی هغې ته وویل: «ای خورې، ته ولې ژاړې؟ څوک لټوې؟» هغې دا ګومان وکړ چې ګوندې هغه باغوان دی نو ورته ویې ویل: «ښاغلیه، که چېرې تا د هغه مړی وړی وي نو ماته ووایه چې هغه دې په کوم ځای کې اچولی دی چې زه لاړه شم او هغه راپیدا کړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_15.mp3', '', 1761754199, 1761754199),
(34493, 'John 20:16', 'John', 20, 16, 'عیسی هغې ته وویل: «مریمې!» مریم هغه ته مخ ورواړاوه او په آرامي ژبه کې یې ورته وویل: «ربوني!» چې معنی یې ده «استاذه!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_16.mp3', '', 1761754199, 1761754199),
(34494, 'John 20:17', 'John', 20, 17, 'عیسی هغې ته وویل: «ماته لاس مه راوړه، ځکه چې زه لا تر‌اوسه پلار ته نه یم تللی. خو زما ورونو یعنې زما شاګردانو ته ورشه او هغوی ته ووایه چې زه اوس خپل پلار ته چې ستاسو پلار هم دې او خپل خدای ته چې ستاسو خدای هم دی، پورته ورځم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_17.mp3', '', 1761754199, 1761754199),
(34495, 'John 20:18', 'John', 20, 18, 'نو مریم مجدلیه لاړه او شاګردانو ته یې وویل چې ما عیسی لیدلی دی. بیا هغوی ته یې د هغه پیغام ورساوه. عیسی خپلو شاګردانو ته ځان ښکاره کوي (متي ۲۸‏:‌۱۶‌‏-‌۲۰ او مرقوس ۱۶‏:‌۱۴‌‏-‌۱۸ او لوقا ۲۴‏:‌۳۶‌‏-‌۴۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_18.mp3', '', 1761754199, 1761754199),
(34496, 'John 20:19', 'John', 20, 19, 'د هماغې یکشنبې په ماښام کله چې شاګردان د یهودیانو د مشرانو له وېرې د تړلو دروازو شاته سره راټول شوي وو، عیسی راغی او د هغوی په منځ کې ودرېده او ویې ویل: «سلام دې وي په تاسو باندې!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_19.mp3', '', 1761754199, 1761754199),
(34497, 'John 20:20', 'John', 20, 20, 'کله چې هغه دا وویل، نو هغوی ته یې خپل لاسونه او خپل بغل وروښودل. کله چې شاګردانو خپل استاذ ولیده نو ډېر خوشحاله شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_20.mp3', '', 1761754199, 1761754199),
(34498, 'John 20:21', 'John', 20, 21, 'عیسی یوځل بیا وویل: «سلام دې وي په تاسو باندې! لکه څنګه چې پلار زه رالېږلی یم نو همداسې زه هم تاسو لېږم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_21.mp3', '', 1761754199, 1761754199),
(34499, 'John 20:22', 'John', 20, 22, 'بیا یې په هغوی وپوکل او ویې ویل: «زما له خوا روح القدس قبول کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_22.mp3', '', 1761754199, 1761754199),
(34500, 'John 20:23', 'John', 20, 23, 'که چېرې تاسو د چا ګناهونه وبخښئ، نو هغوی به وبخښل شي. که تاسو هغوی ونه بخښئ نو هغوی به ونه بخښل شي.» عیسی او توما', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_23.mp3', '', 1761754199, 1761754199),
(34501, 'John 20:24', 'John', 20, 24, 'د دولسو شاګردانو څخه توما چې بل نوم یې غبرګونی ؤ، په هغه وخت کې چې عیسی راغی د نورو سره هلته موجود نه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_24.mp3', '', 1761754199, 1761754199),
(34502, 'John 20:25', 'John', 20, 25, 'نو نورو شاګردانو هغه ته وویل: «مونږ استاذ لیدلی دی.» خو هغه ورته وویل: «ترڅو پورې چې زه د هغه په لاسونو باندې د مېخونو نښې ونه وینم او خپلې ګوتې ورباندې کېنږدم او خپل لاس د هغه د بدن په بغل کېنږدم نو هېڅکله به باور ونه کړم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_25.mp3', '', 1761754199, 1761754199),
(34503, 'John 20:26', 'John', 20, 26, 'یوه هفته وروسته د هغه شاګردان یوځل بیا په کور کې سره راټول شوي وو او توما هم د هغوی سره ؤ. سره له دې چې دروازې بندې وې، خو عیسی راغی او د هغوی په منځ کې ودرېده او ویې ویل: «سلام دې وي په تاسو باندې!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_26.mp3', '', 1761754199, 1761754199),
(34504, 'John 20:27', 'John', 20, 27, 'بیا یې توما ته وویل: «خپلې ګوتې دې دلته کېږده، زما لاسونو ته وګوره او خپل لاسونه راوړاندې کړه او زما په بغل باندې یې کېږده او نور شک مه کوه بلکې ایمان ولره.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_27.mp3', '', 1761754199, 1761754199),
(34505, 'John 20:28', 'John', 20, 28, 'توما وویل: «ای زما استاذه او زما خدایه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_28.mp3', '', 1761754199, 1761754199),
(34506, 'John 20:29', 'John', 20, 29, 'عیسی هغه ته وویل: «په دې خاطر چې زه دې ولیدم نو ایمان دې راوړ؟ بختور دي هغه خلک چې زه یې نه یم لیدلی او ایمان راوړي.» د دې کتاب مقصد', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_29.mp3', '', 1761754199, 1761754199),
(34507, 'John 20:30', 'John', 20, 30, 'عیسی د خپلو شاګردانو په حضور کې ډېرې نورې معجزې وښودلې چې په دې کتاب کې نه دي لیکل شوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_30.mp3', '', 1761754199, 1761754199),
(34508, 'John 20:31', 'John', 20, 31, 'خو دا نښې د دې دپاره لیکل شوي دي چې تاسو په دې ایمان راوړئ چې عیسی هماغه مسیح دی او د خدای زوی دی او په هغه باندې په ایمان راوړلو سره به د هغه په نوم تلپاتې ژوندون ولرئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john20_verse_31.mp3', '', 1761754199, 1761754199),
(34509, 'Romans 11:1', 'Romans', 11, 1, 'زه پوښتنه کوم چې ایا خدای خپل قوم رد کړی دی؟ هېڅکله نه! زه خپله هم اسراییلی یم، د ابراهیم د نسل نه او د بنیامین د قبیلې څخه یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_1.mp3', '', 1761754199, 1761754199),
(34510, 'Romans 11:2', 'Romans', 11, 2, 'خدای خپل هغه قوم نه دی رد کړی چې د مخکې نه یې غوره کړی ؤ. ایا تاسو نه پوهېږئ چې د خدای کلام د الیاس پیغمبر په هکله څه وایي چې هغه څنګه د اسراییلو په خلاف خدای ته شکایت کوي او وایي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans11_verse_2.mp3', '', 1761754199, 1761754199);